package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import org.json.*;
public final class RefreshGestureAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 void set(Object o,String name,Object v)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,v);}
 void gesture(View v){float d=v.getResources().getDisplayMetrics().density;long t=SystemClock.uptimeMillis();v.dispatchTouchEvent(MotionEvent.obtain(t,t,0,80*d,35*d,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+100,2,80*d,165*d,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+200,1,80*d,165*d,0));}
 void reelGesture(View v){float d=v.getResources().getDisplayMetrics().density;long t=SystemClock.uptimeMillis();v.dispatchTouchEvent(MotionEvent.obtain(t,t,0,80*d,130*d,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+100,2,80*d,290*d,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+200,1,80*d,290*d,0));}
 void swipe(View v,boolean up,boolean cancel){float d=v.getResources().getDisplayMetrics().density,x=v.getWidth()*.42f,y=v.getHeight()*.45f,to=y+(up?-1:1)*140*d;long t=SystemClock.uptimeMillis();v.dispatchTouchEvent(MotionEvent.obtain(t,t,0,x,y,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+100,2,x,to,0));v.dispatchTouchEvent(MotionEvent.obtain(t,t+200,cancel?3:1,x,to,0));}
 public void onStart(){Bundle result=new Bundle();try{Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);final ScrollView[] scroll={null};final LinearLayout[] content={null};final int[] requests={0};final Runnable[] complete={null};final Method[] refreshNow={null};
 runOnMainSync(()->{try{Class<?> widget=a.getClassLoader().loadClass("app.kinnect.live.PullRefreshScrollView"),listener=a.getClassLoader().loadClass("app.kinnect.live.PullRefreshScrollView$Listener");Constructor<?> ctor=widget.getDeclaredConstructor(Context.class);ctor.setAccessible(true);scroll[0]=(ScrollView)ctor.newInstance(a);content[0]=new LinearLayout(a);content[0].setOrientation(1);TextView body=new TextView(a);body.setText("Pull refresh fixture");body.setHeight(8000);content[0].addView(body);scroll[0].addView(content[0]);Object proxy=Proxy.newProxyInstance(a.getClassLoader(),new Class[]{listener},(p,m,args)->{if(m.getName().equals("enabled"))return true;if(m.getName().equals("refresh")){requests[0]++;complete[0]=(Runnable)args[0];}return null;});Method bind=widget.getDeclaredMethod("setRefreshListener",listener);bind.setAccessible(true);bind.invoke(scroll[0],proxy);refreshNow[0]=widget.getDeclaredMethod("refreshNow");refreshNow[0].setAccessible(true);a.setContentView(scroll[0]);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(300);
 runOnMainSync(()->{try{gesture(scroll[0]);check(requests[0]==1,"Top pull did not refresh");refreshNow[0].invoke(scroll[0]);check(requests[0]==1,"Duplicate request during refresh");complete[0].run();}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
 runOnMainSync(()->{scroll[0].scrollTo(0,600);check(scroll[0].canScrollVertically(-1),"Fixture did not scroll");gesture(scroll[0]);check(requests[0]==1,"Pull refreshed away from top");scroll[0].scrollTo(0,0);});waitForIdleSync();
 runOnMainSync(()->{try{Class<?> loader=a.getClassLoader().loadClass("app.kinnect.live.MainActivity$RefreshLoader");Object proxy=Proxy.newProxyInstance(a.getClassLoader(),new Class[]{loader},(p,m,args)->null);set(a,"tab","feed");set(a,"onTabRoot",true);set(a,"feedRefresh",proxy);set(a,"content",content[0]);set(a,"lastFeedTap",0L);Method select=a.getClass().getDeclaredMethod("selectNavigation",String.class);select.setAccessible(true);select.invoke(a,"feed");check(requests[0]==2,"Active Feed tap should scroll top and refresh");select.invoke(a,"feed");check(requests[0]==2,"Second tap should refresh");complete[0].run();}catch(Exception e){throw new RuntimeException(e);}});// Exercise actual reel movement twice, keeping the same stage and navigation shell.
 final FrameLayout[] stage={null};final Method show=a.getClass().getDeclaredMethod("showShort",int.class);show.setAccessible(true);
 runOnMainSync(()->{try{set(a,"me",new JSONObject().put("id","audit"));JSONObject author=new JSONObject().put("id","audit").put("name","QA");JSONArray rows=new JSONArray();for(int i=0;i<3;i++)rows.put(new JSONObject().put("id","audit-"+i).put("author",author).put("video","/audit-missing-video.mp4"));set(a,"shortRows",rows);set(a,"shortsFollowing",true);show.invoke(a,1);Field viewport=a.getClass().getDeclaredField("reelViewport");viewport.setAccessible(true);stage[0]=(FrameLayout)viewport.get(a);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(300);
 runOnMainSync(()->swipe(stage[0],true,false));Thread.sleep(450);waitForIdleSync();runOnMainSync(()->{try{Field index=a.getClass().getDeclaredField("shortIndex");index.setAccessible(true);check(index.getInt(a)==2,"Upward reel swipe did not move to next video");Field viewport=a.getClass().getDeclaredField("reelViewport");viewport.setAccessible(true);check(viewport.get(a)==stage[0],"Reel navigation recreated stage");swipe(stage[0],false,false);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(450);waitForIdleSync();runOnMainSync(()->{try{Field index=a.getClass().getDeclaredField("shortIndex");index.setAccessible(true);check(index.getInt(a)==1,"Second reel swipe was blocked or moved incorrectly");swipe(stage[0],true,true);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(250);runOnMainSync(()->{try{Field index=a.getClass().getDeclaredField("shortIndex");index.setAccessible(true);check(index.getInt(a)==1,"Cancelled swipe changed video");show.invoke(a,0);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(100);runOnMainSync(()->{try{swipe(stage[0],false,false);Field busy=a.getClass().getDeclaredField("shortRefreshing");busy.setAccessible(true);check(busy.getBoolean(a),"First reel downward pull did not refresh");int count=stage[0].getChildCount();swipe(stage[0],false,false);check(stage[0].getChildCount()==count,"Duplicate reel refresh indicator");}catch(Exception e){throw new RuntimeException(e);}});
 result.putString("result","PASS: top-only downward refresh; duplicate request guard; no refresh while scrolled; active Feed tap scrolls top and refreshes; actual reel up/down/cancel and retained stage; first-video pull and duplicate guard");runOnMainSync(()->a.finish());finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}
